            stmt.close();
        } catch (Exception e) {
            System.err.println("Failed to fetch bill items: " + e.getMessage());
        }
        return items;
    }

    // Get all bills
    public static List<Bill> getAllBills() {
        List<Bill> bills = new ArrayList<>();
        try {
            Connection conn = DBConnection.getInstance().getConnection();
            String sql = "SELECT \n" +
                    "    B.bill_id,\n" +
                    "    B.bill_date,\n" +
                    "    B.final_amount,\n" +
                    "    B.discount_amount,\n" +
                    "    B.payment_method,\n" +
                    "    B.balance_returned,\n" +
                    "    B.amount_paid,\n" +
                    "    C.full_name AS customer_name,\n" +
                    "    C.customer_id,\n" +
                    "    JSON_ARRAYAGG(\n" +
                    "        JSON_OBJECT(\n" +
                    "            'bill_item_id', BI.bill_item_id,\n" +
                    "            'product_id', BI.product_id,\n" +
                    "            'product_code', BI.product_code,\n" +
                    "            'product_name', BI.product_name,\n" +
                    "            'quantity', BI.quantity,\n" +
                    "            'unit_price', BI.unit_price,\n" +
                    "            'total_price', BI.total_price,\n" +
                    "            'discount_percent', BI.discount_percent,\n" +
                    "            'discount_amount', BI.discount_amount,\n" +
                    "            'final_price', BI.final_price\n" +
                    "        )\n" +
                    "    ) AS bill_items\n" +
                    "FROM bills AS B\n" +
                    "LEFT JOIN bill_items AS BI \n" +
                    "    ON B.bill_id = BI.bill_id\n" +
                    "LEFT JOIN customers AS C \n" +
                    "    ON B.customer_id = C.customer_id\n" +
                    "GROUP BY \n" +
                    "    B.bill_id;";
            PreparedStatement stmt = conn.prepareStatement(sql);
            ResultSet rs = stmt.executeQuery();
            com.fasterxml.jackson.databind.ObjectMapper mapper = new com.fasterxml.jackson.databind.ObjectMapper();
            while (rs.next()) {
                Bill bill = new Bill();
                bill.setBillId(rs.getInt("bill_id"));
                bill.setTotalAmount(rs.getBigDecimal("final_amount"));
                bill.setCustomerName(rs.getString("customer_name"));
                bill.setDiscountAmount(rs.getBigDecimal("discount_amount"));
                bill.setFinalAmount(rs.getBigDecimal("final_amount"));
                bill.setAmountPaid(rs.getBigDecimal("amount_paid"));
                bill.setBalanceReturned(rs.getBigDecimal("balance_returned"));
                bill.setPaymentMethod(rs.getString("payment_method"));
                bill.setBillDate(rs.getTimestamp("bill_date") != null ? rs.getTimestamp("bill_date").toLocalDateTime() : null);
                // Parse bill_items JSON string
                String billItemsJson = rs.getString("bill_items");
                List<BillItem> billItems = new ArrayList<>();
                if (billItemsJson != null && !billItemsJson.equals("[null]")) {
                    try {
                        billItems = Arrays.asList(mapper.readValue(billItemsJson, BillItem[].class));
                    } catch (Exception e) {
                        System.err.println("Failed to parse bill items JSON: " + e.getMessage());
                    }
                }
                bill.setBillItems(billItems);
                bills.add(bill);
            }
            rs.close();
            stmt.close();
        } catch (Exception e) {
            System.err.println("Failed to fetch bills: " + e.getMessage());
        }
        return bills;
    }

    // Update bill status
